mS(a,b){return"\u0397 \u03c4\u03b9\u03bc\u03ae \u03c0\u03c1\u03ad\u03c0\u03b5\u03b9 \u03bd\u03b1 \u03b5\u03af\u03bd\u03b1\u03b9 \u03bc\u03b5\u03c4\u03b1\u03be\u03cd "+A.o(a)+" \u03ba\u03b1\u03b9 "+A.o(b)},
giB(){return"\u0395\u03bb\u03b5\u03b3\u03ba\u03c4\u03ae\u03c2 \u03ba\u03b1\u03c4\u03b1\u03bb\u03cc\u03b3\u03bf\u03c5 \u03b5\u03b9\u03b4\u03ce\u03bd"},
